package io.github.kubanik21crypto.benger;
import org.junit.Test;import static org.junit.Assert.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import java.security.*;import java.security.spec.*;import javax.crypto.*;import javax.crypto.spec.*;import org.json.JSONObject;
public class BrowserPickerSessionTest {
 static final String TOKEN="SYNTHETIC_TOKEN_NOT_REAL";
 static final class Fixture implements AutoCloseable {
  final AtomicInteger calls=new AtomicInteger();final BrowserPickerSession session;final Thread thread;final KeyPair client;
  Fixture()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));client=g.generateKeyPair();session=new BrowserPickerSession(0,"<p>Picker page without credentials</p>",()->{calls.incrementAndGet();return "{\"token\":\""+TOKEN+"\",\"apiKey\":\"synthetic\"}";});thread=new Thread(session::serve);thread.setDaemon(true);thread.start();}
  String path(String suffix){return "/"+session.nonce()+"/"+suffix;}
  Map<String,String> proof(){Map<String,String> h=new HashMap<>();h.put("Origin",session.origin());h.put("X-Benger-Picker-Nonce",session.nonce());h.put("Content-Type","application/json");h.put("Sec-Fetch-Site","same-origin");return h;}
  String request(String method,String path,Map<String,String> h,String body)throws Exception{
   if("POST".equals(method)&&"{}".equals(body))body=new JSONObject().put("publicKey",PickerHandoffCrypto.hex(client.getPublic().getEncoded())).toString();
   URI origin=new URI(session.origin());try(Socket socket=new Socket("127.0.0.1",origin.getPort())){socket.setSoTimeout(3000);StringBuilder raw=new StringBuilder(method+" "+path+" HTTP/1.1\r\nHost: "+h.getOrDefault("Host",origin.getAuthority())+"\r\n");for(Map.Entry<String,String> e:h.entrySet())if(!e.getKey().equals("Host"))raw.append(e.getKey()).append(": ").append(e.getValue()).append("\r\n");raw.append("Content-Length: ").append(body.getBytes(StandardCharsets.UTF_8).length).append("\r\n\r\n").append(body);socket.getOutputStream().write(raw.toString().getBytes(StandardCharsets.UTF_8));ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=socket.getInputStream().read(b))!=-1)bytes.write(b,0,n);return new String(bytes.toByteArray(),StandardCharsets.UTF_8);}
  }
  String decrypt(String response)throws Exception{JSONObject sealed=new JSONObject(response.substring(response.indexOf("\r\n\r\n")+4));KeyAgreement exchange=KeyAgreement.getInstance("ECDH");exchange.init(client.getPrivate());exchange.doPhase(KeyFactory.getInstance("EC").generatePublic(new X509EncodedKeySpec(PickerHandoffCrypto.unhex(sealed.getString("serverKey")))),true);MessageDigest hash=MessageDigest.getInstance("SHA-256");hash.update(exchange.generateSecret());hash.update(session.nonce().getBytes(StandardCharsets.UTF_8));byte[] key=hash.digest(session.origin().getBytes(StandardCharsets.UTF_8));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,PickerHandoffCrypto.unhex(sealed.getString("iv"))));cipher.updateAAD((session.nonce()+"\n"+session.origin()).getBytes(StandardCharsets.UTF_8));return new String(cipher.doFinal(PickerHandoffCrypto.unhex(sealed.getString("ciphertext"))),StandardCharsets.UTF_8);}
  public void close()throws Exception{session.close();thread.join(2000);assertFalse(thread.isAlive());}
 }
 @Test public void pageContainsNoSecretsAndIsNotCachedOrFramed()throws Exception{try(Fixture f=new Fixture()){String page=f.request("GET",f.path("page"),new HashMap<>(),"");assertTrue(page.startsWith("HTTP/1.1 200"));assertTrue(page.contains("Cache-Control: no-store"));assertTrue(page.contains("Referrer-Policy: origin"));assertTrue(page.contains("X-Frame-Options: DENY"));assertFalse(page.contains(TOKEN));assertEquals(0,f.calls.get());assertTrue(f.session.isLoopback());}}
 @Test public void credentialsAreDeliveredOnceThenTheListenerCloses()throws Exception{try(Fixture f=new Fixture()){String result=f.request("POST",f.path("session"),f.proof(),"{}");assertTrue(result.startsWith("HTTP/1.1 200"));assertFalse(result.contains(TOKEN));assertTrue(f.decrypt(result).contains(TOKEN));f.thread.join(2000);assertTrue(f.session.hasDeliveredConfig());assertTrue(f.session.isClosed());assertEquals(1,f.calls.get());try{f.request("POST",f.path("session"),f.proof(),"{}");fail();}catch(IOException expected){}assertEquals(1,f.calls.get());}}
 @Test public void crossOriginAndMissingNonceCannotReadCredentials()throws Exception{try(Fixture f=new Fixture()){Map<String,String> h=f.proof();h.put("Origin","https://unrelated.example");assertTrue(f.request("POST",f.path("session"),h,"{}").startsWith("HTTP/1.1 403"));h=f.proof();h.remove("X-Benger-Picker-Nonce");assertFalse(f.request("POST",f.path("session"),h,"{}").contains(TOKEN));assertEquals(0,f.calls.get());}}
 @Test public void dnsRebindingHostAndCrossSiteFetchAreRejected()throws Exception{try(Fixture f=new Fixture()){Map<String,String> h=f.proof();h.put("Host","unrelated.example");assertTrue(f.request("POST",f.path("session"),h,"{}").startsWith("HTTP/1.1 403"));h=f.proof();h.put("Sec-Fetch-Site","cross-site");assertFalse(f.request("POST",f.path("session"),h,"{}").contains(TOKEN));assertEquals(0,f.calls.get());}}
 @Test public void getAndPreflightDoNotExposeSessionData()throws Exception{try(Fixture f=new Fixture()){assertFalse(f.request("GET",f.path("session"),f.proof(),"").contains(TOKEN));String options=f.request("OPTIONS",f.path("session"),f.proof(),"");assertFalse(options.contains("Access-Control-Allow-Origin"));assertFalse(options.contains(TOKEN));assertEquals(0,f.calls.get());}}
 @Test public void wrongPathOrNonceDoNotConsumeTheCapability()throws Exception{try(Fixture f=new Fixture()){assertTrue(f.request("POST","/wrong/session",f.proof(),"{}").startsWith("HTTP/1.1 404"));Map<String,String> h=f.proof();h.put("X-Benger-Picker-Nonce","0".repeat(64));assertTrue(f.request("POST",f.path("session"),h,"{}").startsWith("HTTP/1.1 403"));assertEquals(0,f.calls.get());}}
 @Test public void oversizedAndChunkedRequestsAreRejected()throws Exception{try(Fixture f=new Fixture()){assertTrue(f.request("POST",f.path("session"),f.proof(),"x".repeat(2049)).startsWith("HTTP/1.1 400"));Map<String,String> h=f.proof();h.put("Transfer-Encoding","chunked");assertTrue(f.request("POST",f.path("session"),h,"{}").startsWith("HTTP/1.1 403"));assertEquals(0,f.calls.get());}}
 @Test public void sessionUrlsContainOnlyAnOpaqueNonce()throws Exception{try(Fixture a=new Fixture();Fixture b=new Fixture()){assertTrue(a.session.nonce().matches("[a-f0-9]{64}"));assertNotEquals(a.session.nonce(),b.session.nonce());assertFalse(a.session.pageUrl().contains(TOKEN));assertNull(new URI(a.session.pageUrl()).getQuery());assertNull(new URI(a.session.pageUrl()).getFragment());}}
 @Test public void portConflictDoesNotFallBackToALanListener()throws Exception{try(Fixture f=new Fixture()){int port=new URI(f.session.origin()).getPort();try{new BrowserPickerSession(port,"page",()->TOKEN);fail();}catch(BindException expected){}}}
}
